// Runs `attempt`, and once more if it fails.
export const retryOnce = async <A>(attempt: () => Promise<A>): Promise<A> => {
  try {
    return await attempt();
  } catch {
    return attempt();
  }
};

import { setTimeout as sleep } from "node:timers/promises";

// Runs `attempt`, and once more, 200 ms later, if it fails.
export const retryOnce = async <A>(attempt: () => Promise<A>): Promise<A> => {
  try {
    return await attempt();
  } catch {
    await sleep(200);
    return attempt();
  }
};

// The welcome line, with the developer's name when Fern knows it.
export const greeting = (name: string | undefined) =>
  name === undefined ? "Hello" : `Hello, ${name}`;

// Runs `work`, logging how long it took.
export const timed = async <A>(label: string, work: () => Promise<A>) => {
  const start = performance.now();
  try {
    return await work();
  } finally {
    console.debug(`${label} took ${Math.round(performance.now() - start)} ms`);
  }
};
